    // ─────────── فصل ۱: سالن آنا پاولونا ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "Anna Pavlovna's Salon", titlePersian = "سالن آنا پاولونا",
        paragraphs = listOf(
            StoryParagraph("It was the year 1805, and all of Europe was at war with Napoleon Bonaparte.", "سال ۱۸۰۵ بود و تمام اروپا در جنگ با ناپلئون بناپارت بود."),
            StoryParagraph("In St. Petersburg, the capital of Russia, the wealthy and powerful gathered in magnificent salons to discuss the news from the front.", "در سنت پترزبورگ، پایتخت روسیه، ثروتمندان و قدرتمندان در سالن‌های باشکوه جمع می‌شدند تا اخبار جبهه را بحث کنند."),
            StoryParagraph("The most famous of these salons belonged to Anna Pavlovna Scherer, a lady-in-waiting to the Empress, a woman of great wit and greater ambition.", "مشهورترین این سالن‌ها مال آنا پاولونا شرر بود، ندیمه امپراتریس، زنی با هوش فراوان و جاه‌طلبی بیشتر."),
            StoryParagraph("On this particular evening in July, her drawing room was filled with princes, counts, diplomats, and generals.", "در این عصر خاص از ماه ژوئیه، اتاق پذیرایی‌اش پر از شاهزادگان، کنت‌ها، دیپلمات‌ها و ژنرال‌ها بود."),
            StoryParagraph("Anna Pavlovna moved among her guests like a master of ceremonies, ensuring that every conversation remained polite and pleasant.", "آنا پاولونا مثل استاد مراسم میان مهمانانش حرکت می‌کرد و مطمئن می‌شد هر گفتگویی مؤدبانه و خوشایند بماند."),
            StoryParagraph("She was not beautiful, and she was no longer young; but she possessed the rare gift of making people feel that they were the most fascinating person in the room.", "او زیبا نبود و جوان هم نبود؛ اما این موهبت نادر را داشت که آدم‌ها را وادار کند حس کنند جذاب‌ترین شخص در اتاقند."),
            StoryParagraph("Prince Vasily Kuragin arrived first, as he always did, a tall and stately man in the formal dress of a courtier.", "شاهزاده واسیلی کوراگین اول رسید، همانطور که همیشه می‌کرد، مردی بلندقد و باوقار در لباس رسمی درباری."),
            StoryParagraph("He was a man of great importance and little substance; he had never learned to read a book, but he had mastered the art of flattery.", "او مردی با اهمیت فراوان و جوهر اندک بود؛ هرگز یاد نگرفته بود کتابی بخواند، اما هنر تملق را کامل آموخته بود."),
            StoryParagraph("His daughter, Helene, was with him — a woman so beautiful that she seemed almost to shine, and so empty that no one had ever heard her say anything memorable.", "دخترش هلن با او بود — زنی اینقدر زیبا که به نظر می‌رسید تقریباً می‌درخشد و اینقدر توخالی که هیچ‌کس هرگز چیزی به‌یادماندنی از او نشنیده بود."),
            StoryParagraph("Prince Vasily's only concern, that evening and every evening, was to find a rich husband for his daughter.", "تنها نگرانی شاهزاده واسیلی، آن شب و هر شب، یافتن شوهری ثروتمند برای دخترش بود."),
            StoryParagraph("His son, Anatole, was elsewhere, probably gambling away money he did not have, or seducing some woman he would not marry.", "پسرش آناتول جای دیگری بود، احتمالاً در حال قمار بردن پولی که نداشت، یا فریب دادن زنی که با او ازدواج نمی‌کرد."),
            StoryParagraph("As the guests mingled, the conversation turned to the war, as it always did.", "همانطور که مهمانان با هم می‌آمیختند، گفتگو به جنگ چرخید، همانطور که همیشه می‌کرد."),
            StoryParagraph("Some of the guests admired Napoleon as a genius; others denounced him as the antichrist.", "برخی از مهمانان ناپلئون را همچون نابغه‌ای تحسین می‌کردند؛ برخی دیگر او را دجال می‌خواندند."),
            StoryParagraph("Anna Pavlovna, as always, had an opinion about everything, and expressed it with a smile that was more impressive than any argument.", "آنا پاولونا مثل همیشه درباره هر چیز نظری داشت و با لبخندی بیانش می‌کرد که از هر استدلالی تأثیرگذارتر بود."),
            StoryParagraph("A new guest entered: a large young man with spectacles, awkward and shy, who seemed uncertain of what to do with his enormous hands.", "مهمان جدیدی وارد شد: مرد جوانی بزرگ با عینک، دست‌وپا چلفتی و خجالتی، که به نظر می‌رسید مطمئن نیست با دست‌های عظیمش چه کند."),
            StoryParagraph("It was Pierre Bezukhov, the illegitimate son of the wealthy Count Bezukhov, who had just returned from studying in Paris.", "پیر بزوخوف بود، پسر نامشروع کنت ثروتمند بزوخوف، که تازه از تحصیل در پاریس برگشته بود."),
            StoryParagraph("Pierre had no social graces, no manners, and no idea that he was being watched with great interest by every unmarried woman and every ambitious mother in the room.", "پیر هیچ نزاکت اجتماعی نداشت، نه آدابی و نه ایده‌ای که تمام زنان مجرد و هر مادر جاه‌طلبی در اتاق با علاقه‌ای فراوان تماشایش می‌کردند."),
            StoryParagraph("He was heir to one of the greatest fortunes in Russia, and that fact alone made him the most eligible bachelor in St. Petersburg.", "او وارث یکی از بزرگ‌ترین ثروت‌های روسیه بود و همین حقیقت به‌تنهایی او را شایسته‌ترین مجرد سنت پترزبورگ می‌کرد."),
            StoryParagraph("Anna Pavlovna greeted him with special warmth, taking his arm as if he were a prize she had won.", "آنا پاولونا با گرمی خاصی پذیرایش شد و بازویش را گرفت گویی جایزه‌ای بود که برده بود."),
            StoryParagraph("'You cannot imagine how I have longed to see you,' she said, and she meant every word, though not for the reasons Pierre supposed.", "گفت: «نمی‌توانی تصور کنی چقدر مشتاق دیدن تو بوده‌ام.» و هر کلمه‌اش را باور داشت، هرچند نه به دلایلی که پیر فرض می‌کرد."),
            StoryParagraph("'I came with Prince Vasily,' Pierre said, awkwardly. 'I do not know anyone here.'", "پیر با دست‌وپا چلفتی گفت: «با شاهزاده واسیلی آمدم. کسی را اینجا نمی‌شناسم.»"),
            StoryParagraph("'You will know everyone soon enough,' Anna Pavlovna replied, and she led him into the room.", "آنا پاولونا پاسخ داد: «به‌زودی همه را خواهی شناخت.» و او را به داخل اتاق برد."),
            StoryParagraph("As Pierre looked around, he caught the eye of a young man standing alone in the corner, an officer in a white uniform, with a face at once proud and sad.", "همانطور که پیر اطراف را نگاه می‌کرد، چشمانش به مرد جوانی افتاد که تنها در گوشه ایستاده بود، افسری با یونیفرم سفید، با چهره‌ای همزمان مغرور و غمگین."),
            StoryParagraph("It was Prince Andrei Bolkonsky, a man who had come to the party for no reason he could explain, a man who found such gatherings tedious beyond words.", "شاهزاده آندری بولکونسکی بود، مردی که به مهمانی آمده بود نه برای دلیلی که بتواند توضیح دهد، مردی که چنین مجلس‌هایی را غیرقابل توصیف کسل‌کننده می‌یافت."),
            StoryParagraph("Pierre and Andrei had met years before, in Petersburg, and had recognized in each other a kind of kinship, an intelligence that did not need to prove itself.", "پیر و آندری سال‌ها پیش، در پترزبورگ، همدیگر را دیده بودند و در همدیگر نوعی خویشاوندی تشخیص داده بودند، هوشی که نیازی نداشت خودش را اثبات کند."),
            StoryParagraph("They moved toward each other, and Anna Pavlovna, seeing this, smiled with satisfaction; she had hoped they would find each other.", "به سمت هم حرکت کردند و آنا پاولونا که این را دید با رضایت لبخند زد؛ امیدوار بود همدیگر را پیدا کنند."),
            StoryParagraph("'Well, Prince, Genoa and Lucca are now no more than family estates of the Bonapartes,' Anna Pavlovna said, turning to Prince Vasily.", "آنا پاولونا رو به شاهزاده واسیلی کرد: «خب، شاهزاده، جنوا و لوکا اکنون چیزی جز املاک خانوادگی بناپارت‌ها نیستند.»"),
            StoryParagraph("'I only want to warn you that if you keep on defending Napoleon and his works, I shall have to quarrel with you,' she added, with a smile.", "افزود با لبخندی: «فقط می‌خواهم هشدارت دهم اگر به دفاع از ناپلئون و کارهایش ادامه دهی، مجبور می‌شوم با تو دعوا کنم.»"),
            StoryParagraph("Andrei rolled his eyes, and Pierre laughed, and the two friends slipped away to a corner of the room where they could talk freely.", "آندری چشمانش را چرخاند و پیر خندید و دو دوست به گوشه‌ای از اتاق لیز خوردند که می‌توانستند آزادانه صحبت کنند."),
            StoryParagraph("'This is a terrible crowd,' Andrei said, with a look of contempt. 'Shall we have supper together somewhere?'", "آندری با نگاهی پر از تحقیر گفت: «این جمعیت افتضاحی است. جایی با هم شام بخوریم؟»"),
            StoryParagraph("Pierre agreed with pleasure, and the two men, having paid their respects to the hostess, made their escape into the night.", "پیر با خوشحالی موافقت کرد و آن دو مرد، پس از احترام گذاشتن به میزبان، به شب گریختند."),
            StoryParagraph("They walked through the dark streets of St. Petersburg, and they talked, as they had talked years before, about everything that mattered.", "در خیابان‌های تاریک سنت پترزبورگ قدم زدند و همانطور که سال‌ها پیش صحبت کرده بودند صحبت کردند، درباره هر چیزی که اهمیت داشت."),
            StoryParagraph("Andrei spoke of his ambition to join the army, to fight against Napoleon, to find glory on the battlefield.", "آندری از جاه‌طلبی‌اش برای پیوستن به ارتش گفت، برای جنگیدن علیه ناپلئون، برای یافتن شهرت در میدان نبرد."),
            StoryParagraph("Pierre spoke of his confusion, his uncertainty, his inability to decide what to do with his life.", "پیر از سردرگمی‌اش گفت، از عدم قطعیتش، از ناتوانی‌اش در تصمیم‌گیری برای اینکه با زندگی‌اش چه کند."),
            StoryParagraph("'How can you not know?' Andrei asked, surprised. 'You are free. You have money. You have no obligations.'", "آندری حیرت‌زده پرسید: «چطور نمی‌دانی؟ آزادی. پول داری. هیچ تعهدی نداری.»"),
            StoryParagraph("'That is precisely the problem,' Pierre replied. 'When you have everything, you have nothing to strive for.'", "پیر پاسخ داد: «دقیقاً همین مشکل است. وقتی همه چیز داری، چیزی برای تلاش نداری.»"),
            StoryParagraph("Andrei nodded, and for a moment he said nothing, and then he spoke of his wife, whom he did not love, and of the child she was carrying, whom he did not want.", "آندری سر تکان داد و لحظه‌ای چیزی نگفت و بعد از همسرش گفت، که دوستش نداشت و از بچه‌ای که حمل می‌کرد، که نمی‌خواست."),
            StoryParagraph("'Never marry, Pierre,' he said, with sudden bitterness. 'Never marry. It is a trap. It destroys everything good in a man.'", "با تلخی ناگهانی گفت: «هرگز ازدواج نکن، پیر. هرگز ازدواج نکن. تله است. هر چیز خوبی در انسان را نابود می‌کند.»"),
            StoryParagraph("Pierre did not know what to say; he had never loved anyone, and he hoped to love someone one day, and he did not want to believe what Andrei was saying.", "پیر نمی‌دانست چه بگوید؛ هرگز کسی را دوست نداشته بود و امیدوار بود روزی کسی را دوست بدارد و نمی‌خواست آنچه آندری می‌گفت را باور کند."),
            StoryParagraph("They parted at dawn, in front of Andrei's house, and they promised to see each other again soon.", "هنگام سحر، مقابل خانه آندری جدا شدند و قول دادند به‌زودی دوباره همدیگر را ببینند."),
            StoryParagraph("Andrei went inside to his cold bed and his pregnant wife; Pierre went to his rooms and lay awake, thinking.", "آندری به داخل رفت، به تخت سردش و همسر باردارش؛ پیر به اتاق‌هایش رفت و بیدار دراز کشید و فکر کرد."),
            StoryParagraph("And so began the story of War and Peace, the story of a generation that lived through the greatest upheaval in European history.", "و اینگونه داستان جنگ و صلح آغاز شد، داستان نسلی که بزرگ‌ترین تحول تاریخ اروپا را زیست."),
            StoryParagraph("It is a story of love and loss, of ambition and disappointment, of courage and cowardice.", "داستانی است از عشق و فقدان، از جاه‌طلبی و ناامیدی، از شجاعت و بزدلی."),
            StoryParagraph("It is a story of two men, so different in temperament, so alike in their search for meaning.", "داستانی است از دو مرد، چنان متفاوت در خو، چنان شبیه در جستجویشان برای معنا."),
            StoryParagraph("It is a story of Russia, of its people, of its soul, of its place in the great drama of history.", "داستانی است از روسیه، از مردمش، از روحش، از جایگاهش در نمایش بزرگ تاریخ.")
        )
    )

    // ─────────── فصل ۲: شاهزاده آندری بولکونسکی ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "Prince Andrei Bolkonsky", titlePersian = "شاهزاده آندری بولکونسکی",
        paragraphs = listOf(
            StoryParagraph("Prince Andrei Bolkonsky was thirty-one years old, and he was already weary of life.", "شاهزاده آندری بولکونسکی سی و یک ساله بود و از قبل از زندگی خسته شده بود."),
            StoryParagraph("He was handsome, intelligent, and admired by everyone; but he found no pleasure in any of it.", "او خوش‌قیافه و باهوش و محبوب همه بود؛ اما هیچ لذتی در هیچ‌کدام نمی‌یافت."),
            StoryParagraph("He was married to Princess Lise, a small and pretty woman whom he had once loved and now could barely tolerate.", "او با شاهزاده خانم لیزا ازدواج کرده بود، زنی کوچک و زیبا که روزی دوستش داشته و حالا به‌سختی تحملش می‌کرد."),
            StoryParagraph("He was going to be a father, and he felt only dread at the prospect.", "پدر می‌شد و تنها هراس در این چشم‌انداز حس می‌کرد."),
            StoryParagraph("He spent his days at parties and dinners, listening to meaningless talk and watching empty gestures.", "روزهایش را در مهمانی‌ها و شام‌ها می‌گذراند، به گفتگوهای بی‌معنا گوش می‌داد و حرکات توخالی را تماشا می‌کرد."),
            StoryParagraph("He spent his evenings at home, reading, thinking, and staring at the ceiling.", "عصرهایش را در خانه می‌گذراند، می‌خواند، فکر می‌کرد و به سقف خیره می‌شد."),
            StoryParagraph("He wondered what the point of anything was, and he found no answer.", "حیران بود هدف هر چیزی چیست و پاسخی نمی‌یافت."),
            StoryParagraph("His only comfort was his sister, Princess Mary, who lived at the family estate of Bald Hills with their father, the old Prince Nikolai Bolkonsky.", "تنها تسلی‌اش خواهرش، شاهزاده خانم ماری بود که در ملک خانوادگی تپه‌های لخت با پدرشان، شاهزاده نیکولای بولکونسکی پیر، زندگی می‌کرد."),
            StoryParagraph("The old prince was a man of iron will and eccentric habits; he had been a general in the time of Catherine the Great, and he never let anyone forget it.", "شاهزاده پیر مردی با اراده آهنین و عادات غریب بود؛ در زمان کاترین کبیر ژنرال بوده و هرگز نمی‌گذاشت کسی فراموشش کند."),
            StoryParagraph("He loved his daughter but treated her with a cruelty that bordered on madness, mocking her, humiliating her, testing her patience every day.", "دخترش را دوست داشت اما با خشونتی که مرز جنون داشت با او رفتار می‌کرد، مسخره‌اش می‌کرد، تحقیرش می‌کرد، هر روز صبرش را می‌آزمود."),
            StoryParagraph("Andrei went to Bald Hills before leaving for the army; he wanted to see his sister and his father one last time.", "آندری پیش از رفتن به ارتش به تپه‌های لخت رفت؛ می‌خواست یک بار آخر خواهرش و پدرش را ببیند."),
            StoryParagraph("The old prince received him coldly, as he received everyone, but he listened to Andrei's plan with attention.", "شاهزاده پیر سرد پذیرایش شد، همانطور که همه را می‌پذیرفت، اما به نقشه آندری با توجه گوش داد."),
            StoryParagraph("'Napoleon is a great man,' the old prince said. 'A great general. A great conqueror. And we are fools if we do not respect him.'", "شاهزاده پیر گفت: «ناپلئون مرد بزرگی است. ژنرال بزرگی. فاتح بزرگی. و اگر به او احترام نگذاریم احمقیم.»"),
            StoryParagraph("'I do not respect him,' Andrei replied. 'I intend to fight against him.'", "آندری پاسخ داد: «من به او احترام نمی‌گذارم. قصد دارم علیه او بجنگم.»"),
            StoryParagraph("'That is because you are young,' the old prince said. 'When you are older, you will understand that war is not about right and wrong. It is about power.'", "شاهزاده پیر گفت: «چون جوانی. وقتی پیرتر شدی می‌فهمی جنگ درباره درست و غلط نیست. درباره قدرت است.»"),
            StoryParagraph("Andrei did not argue; he had learned long ago that arguing with his father was useless.", "آندری بحث نکرد؛ مدت‌ها پیش آموخته بود که بحث با پدرش بی‌فایده است."),
            StoryParagraph("He went to find his sister, who was in her room, as always, praying or reading or playing the piano.", "رفت خواهرش را پیدا کند که مثل همیشه در اتاقش بود، دعا می‌کرد یا می‌خواند یا پیانو می‌زد."),
            StoryParagraph("Princess Mary was not beautiful; her face was plain, and her body was thin, and she was often ill.", "شاهزاده خانم ماری زیبا نبود؛ صورتش معمولی بود و بدنش لاغر و اغلب مریض."),
            StoryParagraph("But she had the most beautiful eyes that Andrei had ever seen, eyes that shone with kindness and faith and a love that seemed to encompass the whole world.", "اما زیباترین چشمانی را داشت که آندری هرگز دیده بود، چشمانی که با مهربانی و ایمان و عشقی می‌درخشیدند که به نظر می‌رسید تمام جهان را در بر می‌گیرد."),
            StoryParagraph("'You are going to the war,' Mary said, and her voice trembled.", "ماری گفت: «داری به جنگ می‌روی.» و صدایش لرزید."),
            StoryParagraph("'Yes,' Andrei said. 'I am going to the war.'", "آندری گفت: «بله. دارم به جنگ می‌روم.»"),
            StoryParagraph("'Why?' Mary asked. 'Why do you have to go?'", "ماری پرسید: «چرا؟ چرا باید بروی؟»"),
            StoryParagraph("'Because I cannot stay here,' Andrei said. 'Because this life is suffocating me. Because I need to do something that matters.'", "آندری گفت: «چون نمی‌توانم اینجا بمانم. چون این زندگی خفه‌ام می‌کند. چون به چیزی نیاز دارم که اهمیت داشته باشد.»"),
            StoryParagraph("Mary did not understand, not really; she had never wanted anything more than to live quietly, to love God, to be kind to those around her.", "ماری نفهمید، نه واقعاً؛ هرگز چیزی بیشتر از زندگی آرام نخواسته بود، دوست داشتن خدا، مهربان بودن با اطرافیانش."),
            StoryParagraph("But she loved her brother, and she did not try to stop him, and she gave him a small icon to wear around his neck.", "اما برادرش را دوست داشت و تلاش نکرد متوقفش کند و آیکون کوچکی به او داد تا دور گردنش بیندازد."),
            StoryParagraph("'Promise me you will wear it always,' she said. 'Promise me you will come back to us.'", "گفت: «قول بده همیشه بپوشی‌اش. قول بده بازگردی پیش ما.»"),
            StoryParagraph("'I promise,' Andrei said, though he did not know whether he could keep such a promise.", "آندری گفت: «قول می‌دهم.» هرچند نمی‌دانست می‌تواند چنین قولی را نگه دارد."),
            StoryParagraph("He said goodbye to his wife Lise, who wept and clung to him and begged him not to go.", "با همسرش لیزا خداحافظی کرد که گریه کرد و به او چسبید و التماس کرد نرود."),
            StoryParagraph("'I will be back before the child is born,' he said. 'Wait for me.'", "گفت: «قبل از تولد بچه بازمی‌گردم. منتظرم بمان.»"),
            StoryParagraph("But he did not look back as he walked away, and he did not feel the sorrow that a man should feel at such a moment.", "اما وقتی دور می‌شد عقب نگاه نکرد و اندوهی که یک مرد باید در چنین لحظه‌ای حس کند را حس نکرد."),
            StoryParagraph("He felt only relief, and anticipation, and a fierce desire to prove himself on the field of battle.", "تنها آسودگی حس کرد و انتظار و میل شدیدی به اثبات خود در میدان نبرد."),
            StoryParagraph("He left Bald Hills, and he left his family, and he left the life that he had known, and he rode toward the war.", "تپه‌های لخت را ترک کرد و خانواده‌اش را و زندگی‌ای که می‌شناخت و به سمت جنگ تاخت."),
            StoryParagraph("He did not know what awaited him there; he did not know whether he would live or die.", "نمی‌دانست آنجا چه در انتظارش است؛ نمی‌دانست زنده می‌ماند یا می‌میرد."),
            StoryParagraph("He only knew that he had to go; that something in him was calling him; that this was his destiny.", "تنها می‌دانست باید برود؛ چیزی درونش فرا می‌خواندش؛ این سرنوشتش بود."),
            StoryParagraph("And so Prince Andrei Bolkonsky went to war, seeking glory, seeking meaning, seeking something he could not name.", "و اینگونه شاهزاده آندری بولکونسکی به جنگ رفت، در جستجوی شهرت، در جستجوی معنا، در جستجوی چیزی که نمی‌توانست نامش را ببرد."),
            StoryParagraph("He would find what he was seeking, but not in the way he expected.", "آنچه می‌جست را می‌یافت اما نه به شیوه‌ای که انتظار داشت."),
            StoryParagraph("He would find pain and suffering, defeat and despair.", "درد و رنج می‌یافت، شکست و ناامیدی."),
            StoryParagraph("And he would find, at last, something that seemed to him more precious than glory: the quiet peace of the sky above the battlefield.", "و سرانجام چیزی می‌یافت که برایش از شهرت گرانبهاتر به نظر می‌رسید: آرامش ساکت آسمان بالای میدان نبرد."),
            StoryParagraph("But that was still to come; for now there was only the road, and the army, and the war.", "اما این هنوز در راه بود؛ برای اکنون تنها جاده بود و ارتش و جنگ.")
        )
    )

    // ─────────── فصل ۳: جنگ و عشق ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "War and Love", titlePersian = "جنگ و عشق",
        paragraphs = listOf(
            StoryParagraph("Andrei joined the Russian army as an adjutant to General Kutuzov, the commander-in-chief.", "آندری به‌عنوان آجودان ژنرال کوتوزوف، فرمانده کل، به ارتش روسیه پیوست."),
            StoryParagraph("He threw himself into the war with all the energy he had, seeking glory, seeking purpose, seeking meaning.", "با تمام انرژی‌اش خود را به جنگ انداخت، در جستجوی شهرت، در جستجوی هدف، در جستجوی معنا."),
            StoryParagraph("He was brave in battle and clever in council; his superiors admired him, and his comrades respected him.", "در نبرد شجاع بود و در شورا باهوش؛ مافوق‌هایش تحسینش می‌کردند و هم‌رزمانش احترامش می‌گذاشتند."),
            StoryParagraph("But he was not happy; he was not even content; he was driven by a hunger that battle could not satisfy.", "اما خوشحال نبود؛ حتی قانع نبود؛ توسط گرسنگی‌ای رانده می‌شد که نبرد نمی‌توانست ارضایش کند."),
            StoryParagraph("The battle of Austerlitz came in December, 1805, the first great battle of the war.", "نبرد آسترلیتز در دسامبر ۱۸۰۵ آمد، نخستین نبرد بزرگ جنگ."),
            StoryParagraph("Andrei carried the flag forward into the chaos, shouting, leading, charging, seeking glory above all things.", "آندری پرچم را به میان آشوب برد، فریاد می‌زد، رهبری می‌کرد، حمله می‌کرد، بیش از هر چیزی در جستجوی شهرت."),
            StoryParagraph("Then a bullet struck him, and he fell, and the world went silent.", "بعد گلوله‌ای به او خورد و افتاد و جهان ساکت شد."),
            StoryParagraph("He lay on the ground, bleeding, alone, staring up at the sky.", "روی زمین دراز کشید، در حال خونریزی، تنها، خیره به آسمان."),
            StoryParagraph("And in that moment, he saw the sky as he had never seen it before: vast, eternal, and utterly indifferent to the small dramas of men.", "و در آن لحظه، آسمان را چنان دید که هرگز قبلاً ندیده بود: عظیم، ابدی و کاملاً بی‌تفاوت به درام‌های کوچک انسان‌ها."),
            StoryParagraph("'How did I not notice this before?' he thought. 'How did I ever think that glory mattered?'", "فکر کرد: «چطور قبلاً این را متوجه نشدم؟ چطور فکر کردم شهرت اهمیت دارد؟»"),
            StoryParagraph("Napoleon himself rode past, and saw Andrei lying on the field, and said, 'That is a fine death.'", "خود ناپلئون از آنجا گذشت و آندری را روی میدان دید و گفت: «مرگ خوبی است.»"),
            StoryParagraph("And Andrei, through his pain, heard the words and thought: 'He is a small man. He is nothing. And so am I.'", "و آندری از میان دردش کلمات را شنید و فکر کرد: «او مرد کوچکی است. هیچ است. و من هم.»"),
            StoryParagraph("He was taken prisoner, and then exchanged, and then sent home to recover.", "اسیر شد و بعد مبادله شد و بعد برای بهبود به خانه فرستاده شد."),
            StoryParagraph("He arrived at Bald Hills just in time to see his wife die in childbirth.", "درست به موقع به تپه‌های لخت رسید که همسرش را در زایمان در حال مرگ ببیند."),
            StoryParagraph("Lise looked at him with terror in her eyes, and tried to speak, and could not, and then she was gone.", "لیزا با ترس در چشمانش نگاهش کرد و تلاش کرد صحبت کند و نتوانست و بعد رفت."),
            StoryParagraph("A son was born, a small and healthy boy, and they named him Nikolai after his grandfather.", "پسری به دنیا آمد، پسرکی کوچک و سالم و به نام نیکولای، به نام پدربزرگش."),
            StoryParagraph("Andrei held the child and wept — for the first time since he was a boy, he wept.", "آندری بچه را در آغوش گرفت و گریست — برای نخستین بار از کودکی، گریست."),
            StoryParagraph("He wept for Lise, for his son, for himself, for everything he had lost and everything he had wasted.", "برای لیزا گریست، برای پسرش، برای خودش، برای هر چیزی که از دست داده بود و هر چیزی که هدر داده بود."),
            StoryParagraph("He resigned his commission and settled at Bald Hills, determined to live quietly, to raise his son, to forget the world.", "استعفا داد و در تپه‌های لخت ساکن شد، مصمم به زندگی آرام، بزرگ کردن پسرش، فراموش کردن جهان."),
            StoryParagraph("But the world would not let him forget; the world was at war, and the war came to him.", "اما جهان نمی‌گذاشت فراموش کند؛ جهان در جنگ بود و جنگ به سراغش آمد."),
            StoryParagraph("Meanwhile, Pierre Bezukhov inherited an enormous fortune — the old Count Bezukhov had died, and Pierre, the illegitimate son, was named his heir.", "در همین حال، پیر بزوخوف ثروت عظیمی را به ارث برد — کنت بزوخوف پیر مرده بود و پیر، پسر نامشروع، وارثش نامیده شد."),
            StoryParagraph("He became Count Bezukhov, one of the richest men in Russia, and suddenly everyone wanted to know him.", "او کنت بزوخوف شد، یکی از ثروتمندترین مردان روسیه و ناگهان همه می‌خواستند بشناسندش."),
            StoryParagraph("Prince Vasily, seeing an opportunity, arranged for Pierre to marry his daughter Helene.", "شاهزاده واسیلی که فرصتی دید، ترتیب ازدواج پیر با دخترش هلن را داد."),
            StoryParagraph("Pierre was flattered, and confused, and lonely; he did not love Helene, but he did not know how to say no.", "پیر خوشحال شد و گیج و تنها؛ هلن را دوست نداشت اما نمی‌دانست چطور بگوید نه."),
            StoryParagraph("They were married in a grand ceremony, and Pierre became the husband of the most beautiful woman in St. Petersburg.", "در مراسمی باشکوه ازدواج کردند و پیر شوهر زیباترین زن سنت پترزبورگ شد."),
            StoryParagraph("But the marriage was a disaster from the start; Helene did not love him, and she made no secret of her affairs.", "اما ازدواج از آغاز فاجعه بود؛ هلن دوستش نداشت و از روابطش پنهان نمی‌کرد."),
            StoryParagraph("Pierre suspected that Helene was having an affair with a man named Dolokhov, and one night, at a dinner, he confronted him.", "پیر مشکوک شد که هلن با مردی به نام دولوخوف رابطه دارد و یک شب، در شامی، با او روبرو شد."),
            StoryParagraph("The confrontation became a duel; Pierre, who had never fired a pistol in anger, shot and wounded Dolokhov.", "روبرویی به دوئل تبدیل شد؛ پیر که هرگز در خشم تپانچه شلیک نکرده بود، شلیک کرد و دولوخوف را زخمی کرد."),
            StoryParagraph("He could have killed him; he could have been killed himself; he did not know which outcome he would have preferred.", "می‌توانست بکشدش؛ می‌توانست خودش کشته شود؛ نمی‌دانست کدام نتیجه را ترجیح می‌داد."),
            StoryParagraph("He left Helene, and he left Moscow, and he wandered through Russia, seeking he knew not what.", "هلن را ترک کرد و مسکو را و در روسیه سرگردان شد، در جستجوی نمی‌دانست چه."),
            StoryParagraph("He joined the Freemasons, hoping to find in their rituals and teachings the meaning that had eluded him.", "به فراماسون‌ها پیوست، به امید یافتن در شعائر و تعالیمشان معنایی که از او گریخته بود."),
            StoryParagraph("For a time, he believed he had found it; he believed in the brotherhood of man, in the moral improvement of the self, in the possibility of a better world.", "برای مدتی باور کرد که یافته؛ به برادری انسان باور داشت، به بهبود اخلاقی خویش، به امکان جهانی بهتر."),
            StoryParagraph("He returned to his estates and tried to improve the lives of his peasants; he built schools, and hospitals, and roads.", "به املاکش بازگشت و تلاش کرد زندگی رعایایش را بهبود دهد؛ مدرسه ساخت و بیمارستان و جاده."),
            StoryParagraph("But the peasants did not understand him, and the other landowners laughed at him, and his reforms came to nothing.", "اما رعایا نمی‌فهمیدندش و دیگر زمین‌داران مسخره‌اش می‌کردند و اصلاحاتش به هیچ انجامید."),
            StoryParagraph("Pierre grew disillusioned, and he began to drink, and to gamble, and to seek forgetfulness in pleasure.", "پیر ناامید شد و شروع کرد به نوشیدن و قمار و جستن فراموشی در لذت."),
            StoryParagraph("And so the years passed, and the war continued, and Russia waited for the storm that was coming.", "و اینگونه سال‌ها گذشتند و جنگ ادامه یافت و روسیه منتظر طوفانی بود که می‌آمد.")
        )
    )

    // ─────────── فصل ۴: ناتاشا روستوا ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "Natasha Rostova", titlePersian = "ناتاشا روستوا",
        paragraphs = listOf(
            StoryParagraph("The Rostov family lived in Moscow, in a large house on Povarskaya Street, and they were the happiest family that anyone knew.", "خانواده روستوف در مسکو زندگی می‌کردند، در خانه‌ای بزرگ در خیابان پووارسکایا و شادترین خانواده‌ای بودند که هر کسی می‌شناخت."),
            StoryParagraph("Count Ilya Rostov was a kind and generous man, who spent money he did not have and loved everyone he met.", "کنت ایلیا روستوف مردی مهربان و سخاوتمند بود که پولی که نداشت خرج می‌کرد و هر کسی را که ملاقات می‌کرد دوست می‌داشت."),
            StoryParagraph("Countess Natalya Rostova was a loving mother, devoted to her children, anxious about their futures, prone to tears and laughter.", "کنتس ناتالیا روستوا مادری دوستدار بود، وقف فرزندانش، نگران آینده‌شان، مستعد اشک و خنده."),
            StoryParagraph("Their eldest daughter, Vera, was cold and correct; their eldest son, Nikolai, was a student and a soldier; their younger son, Petya, was still a boy.", "دختر بزرگشان، ورا، سرد و درست بود؛ پسر بزرگشان، نیکولای، دانشجو و سرباز بود؛ پسر کوچک‌ترشان، پتیا، هنوز بچه بود."),
            StoryParagraph("And then there was Natasha, their second daughter, thirteen years old, and the joy of the whole family.", "و بعد ناتاشا بود، دختر دومشان، سیزده ساله و شادی تمام خانواده."),
            StoryParagraph("Natasha was not beautiful, not in the conventional sense; but there was something about her, some vitality, some joy, some intensity, that made everyone who met her love her.", "ناتاشا زیبا نبود، نه به معنای متعارف؛ اما چیزی در او بود، سرزندگی‌ای، شادی‌ای، شدتی، که هر کسی که ملاقاتش می‌کرد دوستش می‌داشت."),
            StoryParagraph("She sang beautifully, and she danced beautifully, and she laughed with her whole body, and she wept with her whole heart.", "زیبا می‌خواند و زیبا می‌رقصید و با تمام بدنش می‌خندید و با تمام قلبش گریه می‌کرد."),
            StoryParagraph("She had grown up in a house full of love, and she expected the world to be full of love, and she was always surprised when it was not.", "در خانه‌ای پر از عشق بزرگ شده بود و انتظار داشت جهان پر از عشق باشد و همیشه حیرت‌زده می‌شد وقتی نبود."),
            StoryParagraph("In 1809, when Natasha was sixteen, the Rostovs took her to St. Petersburg for the season.", "در ۱۸۰۹، وقتی ناتاشا شانزده ساله بود، روستوف‌ها او را برای فصل به سنت پترزبورگ بردند."),
            StoryParagraph("She was presented at court, and she danced at her first ball, and she was overwhelmed by the glitter and the grandeur of it all.", "در دربار معرفی شد و در نخستین بالماسکه‌اش رقصید و توسط درخشش و شکوه همه‌اش overwhelmed شد."),
            StoryParagraph("Pierre, who was still wandering through Russia in search of meaning, happened to be at the same ball.", "پیر که هنوز در روسیه سرگردان بود در جستجوی معنا، تصادفاً در همان بالماسکه بود."),
            StoryParagraph("He saw Natasha, and he was struck by her energy, her honesty, her absolute lack of pretense.", "ناتاشا را دید و از انرژی‌اش شگفت‌زده شد، از صداقتش، از فقدان مطلق تظاهرش."),
            StoryParagraph("He had known her as a child, but she was no longer a child; she was becoming a woman, and she was becoming a remarkable one.", "او را از کودکی می‌شناخت، اما دیگر بچه نبود؛ زن می‌شد و زنی قابل توجه می‌شد."),
            StoryParagraph("Pierre was thirty-two now, fat and unhappy and married to a woman he loathed.", "پیر حالا سی و دو ساله بود، چاق و ناخوشحال و متأهل به زنی که از او متنفر بود."),
            StoryParagraph("He watched Natasha dance with a young officer, and he felt a pang of something — envy, perhaps, or longing, or simply the recognition of all that he had lost.", "تماشا کرد که ناتاشا با افسر جوانی می‌رقصد و دردی حس کرد — حسادت، شاید، یا اشتیاق، یا تنها تشخیص هر چیزی که از دست داده بود."),
            StoryParagraph("Andrei, meanwhile, had come out of his retirement, at Pierre's insistence, and had begun to take part in the life of society again.", "آندری در همین حال، به اصرار پیر، از گوشه‌نشینی بیرون آمده بود و شروع کرده بود به شرکت دوباره در زندگی اجتماعی."),
            StoryParagraph("He was still grieving for Lise, and still haunted by what he had seen at Austerlitz, and still uncertain of what he wanted from life.", "هنوز برای لیزا عزادار بود و هنوز توسط آنچه در آسترلیتز دیده بود تسخیر می‌شد و هنوز مطمئن نبود از زندگی چه می‌خواهد."),
            StoryParagraph("Pierre brought Andrei to the Rostovs' house, and Andrei met Natasha, and everything changed.", "پیر آندری را به خانه روستوف‌ها برد و آندری با ناتاشا آشنا شد و همه چیز تغییر کرد."),
            StoryParagraph("At first, Andrei was annoyed by Natasha's youth, her energy, her endless chatter.", "اول آندری از جوانی ناتاشا آزرده شد، از انرژی‌اش، از پرحرفی بی‌پایانش."),
            StoryParagraph("He was a man who had grown old before his time, who had seen too much, who had given up on happiness.", "او مردی بود که پیش از موعدش پیر شده، بسیار دیده، از خوشبختی دست کشیده بود."),
            StoryParagraph("But slowly, inevitably, her vitality began to work on him; her laughter, her singing, her absolute joy in being alive.", "اما آرام‌آرام، اجتناب‌ناپذیر، سرزندگی‌اش شروع کرد به کار کردن بر او؛ خنده‌اش، آوازش، شادی مطلقش در زنده بودن."),
            StoryParagraph("He found himself looking for her at parties, seeking her out at dinners, thinking about her when he was alone.", "خود را یافت که در مهمانی‌ها دنبالش می‌گردد، در شام‌ها جستجوش می‌کند، وقتی تنهاست به او فکر می‌کند."),
            StoryParagraph("And one evening, at a ball, when the moonlight fell on her face, he knew that he was in love.", "و یک عصر، در بالماسکه‌ای، وقتی نور ماه بر صورتش افتاد، دانست که عاشق شده."),
            StoryParagraph("He asked her to dance, and she accepted, and they moved together through the crowd as if no one else existed.", "از او خواست برقصند و او پذیرفت و با هم میان جمعیت حرکت کردند گویی هیچ‌کس دیگری وجود ندارد."),
            StoryParagraph("'I love you,' Andrei said, and the words came out before he could think.", "آندری گفت: «دوستت دارم.» و کلمات پیش از آنکه فکر کند بیرون آمدند."),
            StoryParagraph("Natasha looked at him, and her eyes were bright with tears, and she said, 'I love you too.'", "ناتاشا نگاهش کرد و چشمانش از اشک درخشان بود و گفت: «من هم دوستت دارم.»"),
            StoryParagraph("They became engaged, and the whole Rostov family rejoiced, and Pierre was delighted for his friend.", "آن‌ها نامزد شدند و تمام خانواده روستوف شادی کردند و پیر برای دوستش خوشحال شد."),
            StoryParagraph("But Andrei's father, the old Prince Bolkonsky, refused to give his blessing.", "اما پدر آندری، شاهزاده بولکونسکی پیر، از دادن برکتش امتناع کرد."),
            StoryParagraph("'She is too young,' the old prince said. 'She is too frivolous. She is not worthy of you.'", "شاهزاده پیر گفت: «او خیلی جوان است. خیلی سبکسر. لایق تو نیست.»"),
            StoryParagraph("Andrei argued, and pleaded, and finally, his father agreed to a compromise: the marriage would be postponed for one year.", "آندری بحث کرد و التماس کرد و سرانجام پدرش با سازشی موافقت کرد: ازدواج یک سال به تعویق می‌افتاد."),
            StoryParagraph("'If she still loves you in a year,' the old prince said, 'then she will have proven herself worthy.'", "شاهزاده پیر گفت: «اگر یک سال بعد هنوز دوستت داشته باشد، آن وقت ثابت کرده که لایق است.»"),
            StoryParagraph("Andrei went away to his estate to recover his health, and Natasha stayed in Moscow, waiting.", "آندری به ملکش رفت تا سلامت‌اش را بازیابد و ناتاشا در مسکو ماند، منتظر."),
            StoryParagraph("The waiting was hard for Natasha; she was young, and lively, and the months seemed endless.", "انتظار برای ناتاشا سخت بود؛ جوان بود و سرزنده و ماه‌ها بی‌پایان به نظر می‌رسیدند."),
            StoryParagraph("She wrote to Andrei every day, and he wrote to her, but the letters grew shorter, and the loneliness grew deeper.", "هر روز به آندری نامه می‌نوشت و او هم می‌نوشت، اما نامه‌ها کوتاه‌تر می‌شدند و تنهایی عمیق‌تر."),
            StoryParagraph("And then, into this loneliness, came a man who would change everything: Anatole Kuragin.", "و بعد، به این تنهایی، مردی آمد که همه چیز را تغییر می‌داد: آناتول کوراگین."),
            StoryParagraph("Anatole was handsome, charming, and utterly without conscience; he saw Natasha, and he decided he wanted her, and he did not care what damage he caused.", "آناتول خوش‌قیافه بود، جذاب و کاملاً بدون وجدان؛ ناتاشا را دید و تصمیم گرفت می‌خواهدش و اهمیتی نمی‌داد چه خسارتی وارد می‌کند."),
            StoryParagraph("He seduced her with flattery, with attention, with promises he had no intention of keeping.", "با تملق فریبش داد، با توجه، با وعده‌هایی که قصد نگه داشتنشان را نداشت."),
            StoryParagraph("Natasha, lonely and confused, was swept away; she thought she was in love, and she agreed to elope with him.", "ناتاشا، تنها و گیج، ربوده شد؛ فکر کرد عاشق شده و موافقت کرد با او فرار کند."),
            StoryParagraph("But Pierre found out, and stopped the elopement just in time, and told Natasha the truth about Anatole.", "اما پیر فهمید و به موقع جلوی فرار را گرفت و حقیقت را درباره آناتول به ناتاشا گفت."),
            StoryParagraph("Natasha was devastated; she realized what she had almost done, and she was consumed with guilt and shame.", "ناتاشا ویران شد؛ فهمید چه چیزی را تقریباً کرده بود و توسط گناه و شرم خورده شد."),
            StoryParagraph("When Andrei returned and learned what had happened, he was heartbroken; he refused to see Natasha, and he ended the engagement.", "وقتی آندری بازگشت و فهمید چه اتفاقی افتاده، دلشکسته شد؛ از دیدن ناتاشا امتناع کرد و نامزدی را تمام کرد."),
            StoryParagraph("'I cannot forgive her,' Andrei said to Pierre. 'I cannot forget what she did.'", "آندری به پیر گفت: «نمی‌توانم ببخشمش. نمی‌توانم آنچه کرد را فراموش کنم.»"),
            StoryParagraph("'You are wrong,' Pierre said. 'You are wrong to judge her. You are wrong to refuse forgiveness.'", "پیر گفت: «اشتباه می‌کنی. در قضاوتش اشتباه می‌کنی. در امتناع از بخشش اشتباه می‌کنی.»"),
            StoryParagraph("Andrei did not listen; he went back to the army, and Natasha became ill, and both of them suffered in silence.", "آندری گوش نداد؛ به ارتش بازگشت و ناتاشا مریض شد و هر دو در سکوت رنج کشیدند.")
        )
    )

    // ─────────── فصل ۵: جنگ و صلح ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "War and Peace", titlePersian = "جنگ و صلح",
        paragraphs = listOf(
            StoryParagraph("In June 1812, Napoleon invaded Russia with an army of six hundred thousand men.", "در ژوئن ۱۸۱۲، ناپلئون با ارتشی از ششصد هزار مرد به روسیه حمله کرد."),
            StoryParagraph("The Russian army retreated, and the French advanced, and the whole country was plunged into chaos.", "ارتش روسیه عقب‌نشینی کرد و فرانسوی‌ها پیشروی کردند و تمام کشور در آشوب فرو رفت."),
            StoryParagraph("Andrei rejoined the army and was given command of a regiment.", "آندری به ارتش بازگشت و فرماندهی یک هنگ به او داده شد."),
            StoryParagraph("Pierre, who had been wandering through Russia in search of meaning, decided to join the army too.", "پیر که در روسیه سرگردان بود در جستجوی معنا، تصمیم گرفت به ارتش بپیوندد."),
            StoryParagraph("But he did not join as a soldier; he joined as an observer, a man who wanted to see the great events with his own eyes.", "اما نه به‌عنوان سرباز پیوست؛ به‌عنوان ناظر پیوست، مردی که می‌خواست رویدادهای بزرگ را با چشمان خودش ببیند."),
            StoryParagraph("The battle of Borodino was fought on September 7, 1812 — the greatest battle of the war, and one of the bloodiest in history.", "نبرد بورودینو در ۷ سپتامبر ۱۸۱۲ نبرد شد — بزرگ‌ترین نبرد جنگ و یکی از خونین‌ترین در تاریخ."),
            StoryParagraph("Andrei fought in that battle; he fought bravely, as he always did; and he was wounded, as he had been at Austerlitz.", "آندری در آن نبرد جنگید؛ شجاعانه جنگید، همانطور که همیشه می‌کرد؛ و زخمی شد، همانطور که در آسترلیتز شده بود."),
            StoryParagraph("The wound was serious; he was carried from the field on a stretcher, and he did not know whether he would live or die.", "زخم جدی بود؛ روی برانکارد از میدان برده شد و نمی‌دانست زنده می‌ماند یا می‌میرد."),
            StoryParagraph("He was taken to a hospital in Moscow, but then Moscow was abandoned, and the wounded were moved again.", "به بیمارستانی در مسکو برده شد، اما بعد مسکو رها شد و زخمی‌ها دوباره منتقل شدند."),
            StoryParagraph("And so Andrei found himself in a convoy of wounded men, traveling slowly away from the burning city.", "و اینگونه آندری خود را در کاروانی از مردان زخمی یافت، که آهسته از شهر در آتش دور می‌شدند."),
            StoryParagraph("Among the wounded was Anatole Kuragin, whose leg had been shattered by a cannonball.", "میان زخمی‌ها آناتول کوراگین بود که پایش توسط گلوله توپی خرد شده بود."),
            StoryParagraph("Andrei saw him, and remembered everything, and felt — not anger, not hatred, but a strange, sad pity.", "آندری او را دید و همه چیز را به یاد آورد و حس کرد — نه خشم، نه نفرت، بلکه ترحمی عجیب و اندوهناک."),
            StoryParagraph("'He is suffering,' Andrei thought. 'He is suffering as I am suffering. And we are both just men.'", "آندری فکر کرد: «او رنج می‌کشد. او رنج می‌کشد همانطور که من رنج می‌کشم. و ما هر دو فقط انسانیم.»"),
            StoryParagraph("Anatole died a few days later, and Andrei was moved to a hospital where the doctors gave him little hope.", "آناتول چند روز بعد مرد و آندری به بیمارستانی منتقل شد که دکترها امید کمی به او دادند."),
            StoryParagraph("Natasha had been staying with her family on their country estate, but when she heard that Andrei was wounded, she went to him.", "ناتاشا در ملک روستایی خانواده‌اش مانده بود اما وقتی شنید آندری زخمی شده، به نزدش رفت."),
            StoryParagraph("She nursed him, and she loved him, and she asked his forgiveness for what she had done.", "از او مراقبت کرد و دوستش داشت و طلب بخشش کرد برای آنچه کرده بود."),
            StoryParagraph("'I have nothing to forgive you for,' Andrei said. 'I have forgiven you long ago. I only wish that I had not been so proud.'", "آندری گفت: «چیزی برای بخشیدن نداری. خیلی وقت پیش بخشیده‌ام. تنها آرزو می‌کنم آنقدر مغرور نبوده باشم.»"),
            StoryParagraph("They were together for several days, and in that time, Andrei found a kind of peace.", "چند روز با هم بودند و در آن مدت، آندری نوعی آرامش یافت."),
            StoryParagraph("He thought about his life, about all the things he had done and not done, about all the people he had loved and lost.", "به زندگی‌اش فکر کرد، به همه چیزهایی که کرده و نکرده بود، به همه کسانی که دوست داشته و از دست داده بود."),
            StoryParagraph("He thought about the sky over Austerlitz, and about the smallness of glory, and about the greatness of love.", "به آسمان آسترلیتز فکر کرد و به کوچکی شهرت و به بزرگی عشق."),
            StoryParagraph("'Love is the only thing that is real,' he said to Natasha. 'Everything else is illusion.'", "به ناتاشا گفت: «عشق تنها چیزی است که واقعی است. هر چیز دیگری توهم است.»"),
            StoryParagraph("And then, one morning, he died, peacefully, with Natasha and his sister Mary holding his hands.", "و بعد، یک صبح، به‌آرامی مرد، با ناتاشا و خواهرش ماری که دست‌هایش را گرفته بودند."),
            StoryParagraph("His death was a release, not a loss; he had suffered enough, and he had loved enough, and he was ready to go.", "مرگش رهایی بود، نه فقدان؛ به اندازه کافی رنج کشیده بود و به اندازه کافی عشق ورزیده بود و آماده رفتن بود."),
            StoryParagraph("Meanwhile, the Russian army had retreated, and the French had entered Moscow, and the city had caught fire.", "در همین حال، ارتش روسیه عقب‌نشینی کرده بود و فرانسوی‌ها وارد مسکو شده بودند و شهر آتش گرفته بود."),
            StoryParagraph("Pierre stayed in Moscow when everyone else fled; he had a plan — a mad plan — to assassinate Napoleon.", "پیر در مسکو ماند وقتی همه فرار کردند؛ نقشه‌ای داشت — نقشه‌ای دیوانه‌وار — برای ترور ناپلئون."),
            StoryParagraph("But he was captured by French soldiers before he could carry out the plan, and he was made a prisoner of war.", "اما پیش از آنکه بتواند نقشه را اجرا کند توسط سربازان فرانسوی اسیر شد و به اسیر جنگی تبدیل شد."),
            StoryParagraph("The months of his captivity were the hardest of his life, but also the most important.", "ماه‌های اسارتش سخت‌ترین زندگی‌اش بودند، اما همچنین مهم‌ترین."),
            StoryParagraph("He met a peasant named Platon Karataev, a simple man, a kind man, a man who had found in poverty and suffering a peace that Pierre had never known.", "با دهقانی به نام پلاتون کاراتایف آشنا شد، مردی ساده، مردی مهربان، مردی که در فقر و رنج آرامشی یافته بود که پیر هرگز نشناخته بود."),
            StoryParagraph("'Suffering,' Platon said, 'is part of life. We must accept it. We must love it. We must find God in it.'", "پلاتون گفت: «رنج بخشی از زندگی است. باید بپذیریمش. باید دوستش بداریم. باید خدا را در آن بیابیم.»"),
            StoryParagraph("Pierre did not fully understand, but he felt that there was wisdom in the peasant's words, a wisdom that all his years of study had not given him.", "پیر کاملاً نفهمید اما حس کرد در کلمات دهقان خردی هست، خردی که تمام سال‌های مطالعه‌اش به او نداده بود."),
            StoryParagraph("He learned to live in the moment, to accept what came, to find joy in small things.", "یاد گرفت در لحظه زندگی کند، بپذیرد آنچه می‌آید، شادی را در چیزهای کوچک بیابد."),
            StoryParagraph("He learned that happiness is not something you find, but something you make; not something you chase, but something you accept.", "یاد گرفت خوشبختی چیزی نیست که بیابی، بلکه چیزی است که بسازی؛ چیزی نیست که دنبالش بدوی، بلکه چیزی است که بپذیری."),
            StoryParagraph("When the French retreated, and Pierre was freed, he was a different man.", "وقتی فرانسوی‌ها عقب‌نشینی کردند و پیر آزاد شد، مردی متفاوت بود."),
            StoryParagraph("He returned to Moscow, and he found Natasha, who had been through her own suffering, and who had been changed by it too.", "به مسکو بازگشت و ناتاشا را یافت، که او هم از رنج خودش گذشته بود و توسطش تغییر کرده بود."),
            StoryParagraph("They fell in love, truly in love, the kind of love that comes only after suffering, only after loss, only after learning what really matters.", "عاشق شدند، به‌راستی عاشق، همان نوع عشقی که تنها پس از رنج می‌آید، تنها پس از فقدان، تنها پس از آموختن اینکه واقعاً چه چیزی مهم است."),
            StoryParagraph("They married, and they had children, and they lived a simple life on a country estate, and they were happy.", "ازدواج کردند و بچه‌دار شدند و زندگی ساده‌ای در ملکی روستایی داشتند و خوشحال بودند."),
            StoryParagraph("Not the kind of happiness that comes from wealth or fame or pleasure, but the kind that comes from love, and work, and acceptance.", "نه آن نوع خوشبختی که از ثروت یا شهرت یا لذت می‌آید، بلکه آن نوع که از عشق می‌آید و کار و پذیرش."),
            StoryParagraph("And so war ended, and peace began, and the story of the generation that had lived through it came to its quiet conclusion.", "و اینگونه جنگ تمام شد و صلح آغاز شد و داستان نسلی که آن را زیسته بود به پایان آرامش رسید."),
            StoryParagraph("Not a conclusion of triumph or glory, but of love and acceptance and the simple joy of being alive.", "نه پایانی از پیروزی یا شکوه، بلکه از عشق و پذیرش و شادی ساده زنده بودن."),
            StoryParagraph("And that, Tolstoy suggests, is the only victory worth having.", "و این، تولستوی پیشنهاد می‌دهد، تنها پیروزی‌ای است که ارزش داشتن دارد.")
        )
    )

    // ─────────── فصل ۶: معنا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("War and Peace, published between 1865 and 1869, is one of the longest and greatest novels ever written.", "جنگ و صلح، منتشرشده بین ۱۸۶۵ و ۱۸۶۹، یکی از طولانی‌ترین و بزرگ‌ترین رمان‌های تاریخ است."),
            StoryParagraph("It tells the story of five aristocratic families — the Bezukhovs, the Bolkonskys, the Rostovs, the Kuragins, and the Drubetskoys — during the Napoleonic Wars.", "داستان پنج خانواده اشرافی را تعریف می‌کند — بزوخوف‌ها، بولکونسکی‌ها، روستوف‌ها، کوراگین‌ها و دروبتسکوی‌ها — در طول جنگ‌های ناپلئونی."),
            StoryParagraph("But it is not merely a historical novel; it is a philosophical meditation on history, on free will, on the meaning of life.", "اما تنها یک رمان تاریخی نیست؛ مراقبه‌ای فلسفی است درباره تاریخ، درباره اراده آزاد، درباره معنای زندگی."),
            StoryParagraph("Tolstoy argues that history is not made by great men, but by millions of small actions, each insignificant in itself, all together irresistible.", "تولستوی استدلال می‌کند تاریخ توسط مردان بزرگ ساخته نمی‌شود، بلکه توسط میلیون‌ها عمل کوچک، هر یک به‌خودی‌خود بی‌اهمیت، همه با هم مقاومت‌ناپذیر."),
            StoryParagraph("Napoleon thought he was shaping events, but he was being carried by them, as a leaf is carried by a stream.", "ناپلئون فکر می‌کرد رویدادها را شکل می‌دهد، اما توسط آنها برده می‌شد، همانطور که برگی توسط جریانی برده می‌شود."),
            StoryParagraph("This insight, that the individual is both free and determined, is central to the novel's philosophy.", "این بینش، که فرد هم آزاد و هم تعیین‌شده است، محوری در فلسفه رمان است."),
            StoryParagraph("Andrei and Pierre, the two central characters, embody two different responses to this paradox.", "آندری و پیر، دو شخصیت اصلی، دو پاسخ متفاوت به این پارادوکس را مجسم می‌کنند."),
            StoryParagraph("Andrei seeks glory, seeks meaning, seeks something that will lift him above the ordinary; but he finds that glory is empty, and meaning is elusive, and the only thing that matters is love.", "آندری در جستجوی شهرت است، در جستجوی معنا، در جستجوی چیزی که بالاتر از معمولی ببردش؛ اما می‌یابد شهرت توخالی است و معنا گریزان و تنها چیزی که اهمیت دارد عشق است."),
            StoryParagraph("Pierre drifts, wanders, seeks in pleasure and in philosophy and in good works; but he finds that nothing satisfies him until he learns to accept, to live simply, to love without expectation.", "پیر سرگردان است، در لذت و فلسفه و کارهای خوب می‌جوید؛ اما می‌یابد هیچ چیز ارضایش نمی‌کند تا وقتی یاد می‌گیرد بپذیرد، ساده زندگی کند، بدون انتظار عشق بورزد."),
            StoryParagraph("Natasha, who begins as a girl full of joy and ends as a woman full of wisdom, is the heart of the novel.", "ناتاشا، که به‌عنوان دختری پر از شادی آغاز می‌کند و به‌عنوان زنی پر از خرد پایان می‌یابد، قلب رمان است."),
            StoryParagraph("She suffers, she fails, she falls in love and out of love and back in love; but she never loses her vitality, her honesty, her capacity for life.", "رنج می‌کشد، شکست می‌خورد، عاشق می‌شود و از عشق بیرون می‌آید و دوباره عاشق می‌شود؛ اما هرگز سرزندگی‌اش را از دست نمی‌دهد، نه صداقتش، نه ظرفیتش برای زندگی."),
            StoryParagraph("The novel is about Russia, about its people, about its soul; but it is also about everyone, about humanity, about the universal experience of being alive.", "رمان درباره روسیه است، درباره مردمش، درباره روحش؛ اما درباره همه هم هست، درباره بشریت، درباره تجربه جهانی زنده بودن."),
            StoryParagraph("Tolstoy wrote the novel over seven years, drawing on his own experience as a soldier in the Crimean War, on his study of history, on his observation of human nature.", "تولستوی رمان را در طول هفت سال نوشت، از تجربه خودش به‌عنوان سرباز در جنگ کریمه بهره برد، از مطالعه‌اش در تاریخ، از مشاهده‌اش از طبیعت انسانی."),
            StoryParagraph("He revised it seven times; he rewrote passages again and again; he was never fully satisfied with it.", "هفت بار بازنویسی‌اش کرد؛ قطعات را بارها و بارها بازنویسی کرد؛ هرگز کاملاً راضی نبود از آن."),
            StoryParagraph("And yet, in the end, he produced something that no one else has ever quite equaled: a novel that is both epic and intimate, both historical and philosophical, both Russian and universal.", "و با این حال، در پایان، چیزی تولید کرد که هیچ‌کس دیگری هرگز کاملاً همتایش را نیاورده: رمانی که هم حماسی و هم صمیمی است، هم تاریخی و هم فلسفی، هم روسی و هم جهانی."),
            StoryParagraph("The title, War and Peace, is often misunderstood; it does not mean war and then peace, but war and peace as two sides of the same coin.", "عنوان، جنگ و صلح، اغلب اشتباه فهمیده می‌شود؛ یعنی جنگ و بعد صلح نیست، بلکه جنگ و صلح همچون دو روی یک سکه."),
            StoryParagraph("War is not the opposite of peace; it is the continuation of peace by other means.", "جنگ متضاد صلح نیست؛ ادامه صلح با وسایل دیگر است."),
            StoryParagraph("And peace is not the absence of war; it is the presence of something deeper, something that war cannot destroy.", "و صلح نبود جنگ نیست؛ حضور چیزی عمیق‌تر است، چیزی که جنگ نمی‌تواند نابودش کند."),
            StoryParagraph("That something, Tolstoy suggests, is love; love between man and woman, between parent and child, between friend and friend, between all human beings.", "آن چیز، تولستوی پیشنهاد می‌دهد، عشق است؛ عشق بین مرد و زن، بین پدر و فرزند، بین دوست و دوست، بین همه انسان‌ها."),
            StoryParagraph("And this love, this simple, ordinary, everyday love, is the only thing that can survive the catastrophes of history.", "و این عشق، این عشق ساده و معمولی و روزمره، تنها چیزی است که می‌تواند از فجایع تاریخ جان سالم برد."),
            StoryParagraph("It is not heroic love, not passionate love, not the love of romance novels.", "عشق قهرمانانه نیست، عشق پرشور نیست، عشق رمان‌های عاشقانه نیست."),
            StoryParagraph("It is the love that Pierre finds when he is a prisoner, the love that Andrei finds when he is dying, the love that Natasha finds when she has lost everything else.", "عشقی است که پیر می‌یابد وقتی اسیر است، عشقی که آندری می‌یابد وقتی در حال مرگ است، عشقی که ناتاشا می‌یابد وقتی هر چیز دیگری را از دست داده."),
            StoryParagraph("It is the love that is not earned but given, not deserved but shared, not possessed but lived.", "عشقی است که نه به دست می‌آید بلکه داده می‌شود، نه سزاوارش می‌شویم بلکه قسمت می‌شود، نه مالکش می‌شویم بلکه زندگی‌اش می‌کنیم."),
            StoryParagraph("War and Peace is not a novel to be read quickly; it is a novel to be lived, over many weeks or months, as one lives a life.", "جنگ و صلح رمانی نیست که سریع خوانده شود؛ رمانی است که زیسته شود، در طول هفته‌ها یا ماه‌ها، همانطور که زندگی‌ای زیسته می‌شود."),
            StoryParagraph("It demands patience, and attention, and willingness to be changed.", "صبر می‌خواهد و توجه و آمادگی برای تغییر کردن."),
            StoryParagraph("But for those who give it what it asks, it gives back something that no other novel quite gives: a vision of life that is both honest and hopeful, both tragic and joyful, both human and divine.", "اما برای کسانی که به آنچه می‌خواهد می‌دهند، چیزی پس می‌دهد که هیچ رمان دیگری کاملاً نمی‌دهد: بینشی از زندگی که هم صادق و هم امیدوار است، هم تراژیک و هم شادمانه، هم انسانی و هم الهی."),
            StoryParagraph("Tolstoy did not believe in easy answers, and he did not give any in his novel.", "تولستوی به پاسخ‌های آسان باور نداشت و در رمانش هیچ‌کدام را نداد."),
            StoryParagraph("He did not tell us how to live; he showed us how his characters tried to live, and how they failed, and how they found, at last, something like meaning.", "به ما نگفت چگونه زندگی کنیم؛ نشانمان داد شخصیت‌هایش چگونه تلاش کردند زندگی کنند و چگونه شکست خوردند و چگونه یافتند، در پایان، چیزی شبیه معنا."),
            StoryParagraph("And in that showing, he gave us something more valuable than any teaching: the gift of seeing our own lives with new eyes.", "و در آن نشان دادن، چیزی ارزشمندتر از هر تعلیمی به ما داد: هدیه دیدن زندگی‌های خودمان با چشمانی نو."),
            StoryParagraph("We are all, in a sense, Andrei and Pierre and Natasha; we all seek glory and find it empty; we all wander and find our way home; we all suffer and learn to love.", "همه‌مان به نوعی آندری و پیر و ناتاشا هستیم؛ همه‌مان در جستجوی شهرتیم و توخالی می‌یابیمش؛ همه‌مان سرگردانیم و راه خانه را می‌یابیم؛ همه‌مان رنج می‌کشیم و یاد می‌گیریم عشق بورزیم."),
            StoryParagraph("And the story of our lives, like the story of War and Peace, is not about the great events we witness, but about the small moments we live.", "و داستان زندگی‌های ما، همچون داستان جنگ و صلح، درباره رویدادهای بزرگی که شاهدشان هستیم نیست، بلکه درباره لحظه‌های کوچکی که زندگی می‌کنیم."),
            StoryParagraph("The kiss of a child, the smile of a friend, the comfort of a warm fire on a cold night.", "بوسه کودک، لبخند دوست، آسودگی آتش گرم در شبی سرد."),
            StoryParagraph("These are the things that matter, Tolstoy suggests; these are the things that last.", "این‌ها چیزهایی هستند که اهمیت دارند، تولستوی پیشنهاد می‌دهد؛ این‌ها چیزهایی هستند که می‌مانند."),
            StoryParagraph("And in the end, when everything else has been stripped away, only love remains.", "و در پایان، وقتی هر چیز دیگری برداشته شده، تنها عشق باقی است."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("For the story of war and peace is the story of every generation, in every time, in every place.", "زیرا داستان جنگ و صلح داستان هر نسلی است، در هر زمان، در هر مکان."),
            StoryParagraph("It is the story of us all.", "داستان همه ماست.")
        )
    )
}